#!/usr/bin/env node
/*
 * Deterministic evidence checker for prism v0.2 (the keystone rung).
 *
 * The Evidence pass claims a finding is SUPPORTED by citing `file:line — quote`.
 * An LLM can fabricate a plausible-looking citation that satisfies the schema.
 * This script makes the central claim machine-checkable the same way
 * parse-findings.js made discovery parsing deterministic: for each finding it
 * confirms the file exists, the line range is valid, and the quoted text
 * actually appears at (or very near) the cited lines. A finding that fails is
 * auto-downgraded so a hallucinated quote can never ship as SUPPORTED.
 *
 * It ALSO computes the fingerprint in code (LLMs cannot compute sha1), so
 * cross-run dedup is stable instead of freehand hex that changes every run.
 *
 * Input  (stdin or file): a JSON array of finding records v2 (see prism SKILL.md).
 * Output (stdout): the same array, each record annotated with:
 *   - fingerprint          : recomputed deterministically (overwrites model value)
 *   - status               : downgraded to SUSPECTED if a SUPPORTED/REPRODUCED
 *                            claim's quote does not verify
 *   - confidence.evidence_strength : clamped to what actually verified
 *   - _evidence_check      : {checked, quote_found, matched_lines, note}
 *
 * Downgrade contract (never silently keep a bogus SUPPORTED):
 *   SUPPORTED/REPRODUCED + file missing        -> SUSPECTED  (missing: FILE_NOT_FOUND)
 *   SUPPORTED/REPRODUCED + lines out of range  -> SUSPECTED  (missing: LINES_OUT_OF_RANGE)
 *   SUPPORTED/REPRODUCED + quote not found      -> SUSPECTED  (missing: EVIDENCE_QUOTE_MISMATCH)
 *   REPRODUCED is only trusted when reproduction.status === 'REPRODUCED' AND the
 *     static quote also verifies; otherwise it falls back to the SUPPORTED rules.
 *
 * --rev <sha> (the merge gate's mode; everything below is OFF without it, and the default
 * mode's output is byte-for-byte what it was before --rev existed):
 *   - files are read from the commit (`git cat-file blob <sha>:./<path>`, relative to the
 *     <repo-root> directory), never from the working tree, so a report pins to the head it
 *     reviewed even when the tree moves during the review. git's tree lookup is exact: a path
 *     whose letter case differs from the committed one is FILE_NOT_FOUND here even where the
 *     default mode's case-insensitive filesystem read would succeed.
 *   - `file` must stay inside <repo-root>: an absolute path under the root is made relative, a
 *     leading slash is tried as repo-rooted first; a path that leaves the root (`..`, another
 *     drive, an absolute path elsewhere) is not read and becomes PATH_OUTSIDE_ROOT (the default
 *     mode keeps its second-chance absolute read, which cross-repository design reviews rely on).
 *     A directory is FILE_NOT_FOUND; a symlink, a submodule or an LFS pointer is
 *     UNREADABLE_AT_REV (the committed object is not the file's text, so no code change can make
 *     the record verify: route it to a person).
 *   - REJECTED records that carry evidence get their quotes checked too. The result lands only
 *     in `_evidence_check` (status, missing and confidence are untouched), so a "fixed" claim
 *     can be verified against the fixing commit without ever becoming a ground.
 *   - `_evidence_check.quote_lines`: the line numbers the quotes actually sit on (every quote of
 *     at least 8 loose characters, the idea gate's minimum; sorted, unique). `matched_lines`
 *     keeps its old meaning (the cited window, `from-to`) on the branches that had it.
 *   - every record's `_evidence_check.rev` is the commit it was checked at.
 *   - git runs with the GIT_DIR / GIT_WORK_TREE and GIT_CONFIG_* families removed from the
 *     environment, fsmonitor and hooks off, and a 60 s timeout. A git that cannot answer (missing, timed out, repository gone, blob past
 *     256 MB) is never a verdict on a record: `runAt` throws GitUnavailable and the CLI exits 1.
 *   - an unreadable input, invalid JSON, a non-array, an unknown rev, a missing root or a
 *     stray option prints nothing and exits 1 (the default mode prints `[]` for an unreadable
 *     input and exits 0, as before; it now refuses extra arguments).
 *
 * The default mode never throws, never mutates source files, no deps. Windows/POSIX safe.
 *
 * Usage:
 *   node verify-evidence.js <records.json> <repo-root> > checked.json
 *   node verify-evidence.js <records.json> <repo-root> --rev <sha> > checked.json
 *   node verify-evidence.js --selftest
 *
 * SINGLE-SOURCED: canonical = prism-all/verify-evidence.js; prism-codex + prism
 * copies are generated by skills/sync-review-parsers.sh. Edit ONLY the canonical.
 */
'use strict';
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const GROUNDED = new Set(['SUPPORTED', 'REPRODUCED']);
const CTX = 2;                 // allow the quote to sit within +/-CTX of the cited lines
const NL = /\r\n|\n|\r/;
const MIN_QUOTE_LINES = 8;     // loose characters a quote needs to contribute to quote_lines (= verify-ideas MIN_QUOTE)

// Normalize a path for hashing: repo-relative, forward slashes, no leading ./,
// lowercased ONLY on Windows-style drive-letter inputs (case-insensitive FS).
function normPathForHash(file, repoRoot) {
  if (!file) return '<none>';
  let f = String(file).replace(/\\/g, '/');
  if (repoRoot) {
    const r = String(repoRoot).replace(/\\/g, '/').replace(/\/+$/, '');
    if (f.startsWith(r + '/')) f = f.slice(r.length + 1);
  }
  f = f.replace(/^\.\//, '');
  if (/^[a-zA-Z]:\//.test(f)) f = f.toLowerCase();   // drive letter => case-insensitive
  return f;
}

// A short, stable slug of the claim so two distinct defects in the same
// symbol+category do NOT collide (the review's A3-1 collision case).
function claimStem(claim) {
  const s = String(claim == null ? '' : claim)
    .toLowerCase()
    .replace(/[`'"]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean)
    .slice(0, 8)
    .join('-');
  return s || '<none>';
}

function computeFingerprint(rec, repoRoot) {
  const file = normPathForHash(rec.file, repoRoot);
  const symbol = rec.symbol ? String(rec.symbol) : '<none>';
  const category = rec.category ? String(rec.category) : '<none>';
  const stem = claimStem(rec.claim);
  const basis = `${file}|${symbol}|${category}|${stem}`;
  return {
    fingerprint: crypto.createHash('sha1').update(basis).digest('hex').slice(0, 12),
    unpinned: !rec.file,   // file:null findings are excluded from CI dedup
  };
}

// Parse "lines" which may be "84-102", "98", 98, or [84,102].
function parseLines(lines) {
  if (lines == null) return null;
  if (Array.isArray(lines)) {
    const a = Number(lines[0]), b = Number(lines[lines.length - 1]);
    return Number.isFinite(a) ? [a, Number.isFinite(b) ? b : a] : null;
  }
  const m = String(lines).match(/(\d+)\s*(?:-\s*(\d+))?/);
  if (!m) return null;
  const a = Number(m[1]), b = m[2] ? Number(m[2]) : a;
  return [Math.min(a, b), Math.max(a, b)];
}

// Pull the quoted substring out of an evidence entry like
// `src/auth.py:98 — token record remains active after update`.
function quoteFromEvidence(ev) {
  const s = String(ev == null ? '' : ev);
  // Prefer text after an em/en dash or ' - ' separator; else the whole string.
  const m = s.match(/[—–]\s*(.+)$/) || s.match(/\s-\s+(.+)$/);
  return (m ? m[1] : s).trim();
}

// Loose containment: collapse whitespace, case-insensitive, so trivial
// reflow/indent differences don't cause false mismatches while a fabricated
// quote (absent from the file) still fails.
function loose(s) {
  return String(s).replace(/\s+/g, ' ').trim().toLowerCase();
}

// The quote matcher, shared with verify-ideas.js so idea grounds are checked by the exact same
// rule as evidence quotes: the cited lines +/-CTX, loosely joined, must contain the quote.
function quoteWindow(srcLines, range) {
  const from = Math.max(1, range[0] - CTX), to = Math.min(srcLines.length, range[1] + CTX);
  return { from, to, text: loose(srcLines.slice(from - 1, to).join(' ')) };
}
function quoteInWindow(windowText, quote) {
  return windowText.indexOf(loose(quote)) !== -1;
}

function checkOne(rec, repoRoot) {
  const out = Object.assign({}, rec);
  out.confidence = Object.assign({}, rec.confidence);
  const fp = computeFingerprint(rec, repoRoot);
  out.fingerprint = fp.fingerprint;
  if (fp.unpinned) out.unpinned = true;

  if (!GROUNDED.has(rec.status)) {
    out._evidence_check = { checked: false, note: 'status not grounded — no quote check' };
    return out;
  }

  const downgrade = (missing) => {
    out.status = 'SUSPECTED';
    out.missing = missing;
    out.confidence.evidence_strength = 'NONE';
    out.confidence.label = 'LOW';
    out._evidence_check = { checked: true, quote_found: false, note: missing };
    return out;
  };

  if (!rec.file) return downgrade('FILE_NULL_ON_GROUNDED');
  const abs = repoRoot ? path.join(repoRoot, rec.file) : rec.file;
  let src;
  try { src = fs.readFileSync(abs, 'utf8'); }
  catch (_) {
    // second chance: maybe rec.file was already absolute
    try { src = fs.readFileSync(rec.file, 'utf8'); }
    catch (__) { return downgrade('FILE_NOT_FOUND'); }
  }
  const srcLines = src.split(NL);
  const range = parseLines(rec.lines);
  if (!range) return downgrade('LINES_UNPARSEABLE');
  if (range[0] < 1 || range[1] > srcLines.length) return downgrade('LINES_OUT_OF_RANGE');

  // Gather the cited window (+/- context) and check each evidence quote against it.
  const { from, to, text: windowText } = quoteWindow(srcLines, range);
  const evList = Array.isArray(rec.evidence) ? rec.evidence : (rec.evidence ? [rec.evidence] : []);
  if (evList.length === 0) return downgrade('EVIDENCE_EMPTY');

  const quotes = evList.map(quoteFromEvidence).filter((q) => q.length >= 3);
  const anyFound = quotes.some((q) => quoteInWindow(windowText, q));
  if (!anyFound) return downgrade('EVIDENCE_QUOTE_MISMATCH');

  // Verified. REPRODUCED keeps STRONG only if reproduction actually ran+reproduced.
  const repro = rec.reproduction && rec.reproduction.status;
  if (rec.status === 'REPRODUCED' && repro !== 'REPRODUCED') {
    out.status = 'SUPPORTED';
    out.confidence.evidence_strength = 'MEDIUM';
    out._evidence_check = { checked: true, quote_found: true, note: 'quote OK but reproduction.status != REPRODUCED -> SUPPORTED' };
    return out;
  }
  out._evidence_check = { checked: true, quote_found: true, matched_lines: `${from}-${to}`, note: 'verified' };
  return out;
}

function run(records, repoRoot) {
  const arr = Array.isArray(records) ? records : [];
  return arr.map((r) => checkOne(r || {}, repoRoot));
}

// ---------------------------------------------------------------- --rev mode

// A git failure that is not "this path is not in that commit": a missing git, a stuck or killed
// child, a repository that vanished, a blob past maxBuffer. It is never a verdict on the record;
// runAt throws it and the CLI exits 1 with the reason, so a gate retries instead of recording
// SUSPECTED for a healthy file.
class GitUnavailable extends Error {}

// git reads the repository named by -C with its own configuration: the GIT_DIR family and the
// GIT_CONFIG_* family a surrounding hook or shell exported are dropped, fsmonitor and hooks are off.
const GIT_ENV_OVERRIDES = ['GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_COMMON_DIR', 'GIT_PREFIX', 'GIT_OBJECT_DIRECTORY', 'GIT_ALTERNATE_OBJECT_DIRECTORIES', 'GIT_NAMESPACE', 'GIT_CONFIG_PARAMETERS', 'GIT_CONFIG_COUNT', 'GIT_CONFIG_GLOBAL', 'GIT_CONFIG_SYSTEM'];
function gitEnv() {
  const env = Object.assign({}, process.env);
  for (const k of Object.keys(env)) if (GIT_ENV_OVERRIDES.indexOf(k) !== -1 || /^GIT_CONFIG_(KEY|VALUE)_\d+$/.test(k)) delete env[k];
  return env;
}
const GIT_SAFE = ['-c', 'core.fsmonitor=false', '-c', 'core.hooksPath=', '-c', 'core.pager=cat'];
const GIT_TIMEOUT_MS = 60000;
// Runs git; returns {out} or {status, err} for a non-zero exit; throws GitUnavailable for a child
// that did not run to completion (spawn error, timeout, signal, output past maxBuffer).
function gitRun(repoRoot, args) {
  try {
    return { out: execFileSync('git', ['-C', repoRoot].concat(GIT_SAFE, args), { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'], windowsHide: true, timeout: GIT_TIMEOUT_MS, env: gitEnv() }) };
  } catch (e) {
    if (e && typeof e.status === 'number' && !e.signal && e.code !== 'ENOBUFS') return { status: e.status, err: String(e.stderr || '').trim() };
    throw new GitUnavailable(`git ${args[0]} did not complete in ${repoRoot}: ${e && (e.code || e.signal || e.message)}`);
  }
}

// `file` as git names it under the root (forward slashes), or null when it leaves the root. A
// repo-rooted path with a leading slash is tried under the root first (as the default mode's
// path.join does); a drive or UNC path is taken as is.
function repoRelative(file, repoRoot) {
  const root = path.resolve(String(repoRoot));
  const f = String(file).replace(/\\/g, '/');
  const inside = (abs) => {
    const rel = path.relative(root, abs);
    if (!rel || rel === '..' || rel.startsWith('..' + path.sep) || path.isAbsolute(rel)) return null;
    return rel.split(path.sep).join('/');
  };
  if (/^[a-zA-Z]:\//.test(f) || f.startsWith('//')) return inside(path.resolve(f));
  return inside(path.resolve(path.join(root, f))) || (f.startsWith('/') ? inside(path.resolve(f)) : null);
}

const LFS_POINTER = /^version https:\/\/git-lfs\.github\.com\/spec\/v1\r?$/m;
// The blob at <sha>:<rel>, read relative to the -C directory (`./`, so a root below the top level
// stays confined). {text} for a regular file; {code} FILE_NOT_FOUND for a missing path or a tree,
// UNREADABLE_AT_REV for a symlink, a submodule or an LFS pointer (the committed object is not the
// file's text, and no code change can make it verify).
function gitBlob(repoRoot, sha, rel) {
  const ls = gitRun(repoRoot, ['ls-tree', sha, '--', `./${rel}`]);
  if (ls.status) return { code: 'FILE_NOT_FOUND' };
  const m = /^(\d{6}) (\w+) /.exec(ls.out);
  if (!m) return { code: 'FILE_NOT_FOUND' };
  if (m[2] === 'tree') return { code: 'FILE_NOT_FOUND' };
  if (m[2] !== 'blob' || m[1] === '120000') return { code: 'UNREADABLE_AT_REV' };
  const cat = gitRun(repoRoot, ['cat-file', 'blob', `${sha}:./${rel}`]);
  if (cat.status) return { code: 'FILE_NOT_FOUND' };
  if (LFS_POINTER.test(cat.out.slice(0, 200))) return { code: 'UNREADABLE_AT_REV' };
  return { text: cat.out };
}

// Where each window line starts in quoteWindow()'s text: that text is the lines joined by a space
// and collapsed by loose(), which equals the lines' own loose() forms joined by one space with the
// empty ones dropped (the selftest asserts the two agree). One offset per line, nothing per
// character.
function lineStarts(srcLines, from, to) {
  const starts = [];
  let len = 0;
  for (let i = from; i <= to; i++) {
    const seg = loose(srcLines[i - 1]);
    if (!seg) continue;
    if (len) len += 1;
    starts.push({ line: i, at: len });
    len += seg.length;
  }
  return starts;
}
function lineAt(starts, offset) {
  let lo = 0, hi = starts.length - 1;
  while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (starts[mid].at <= offset) lo = mid; else hi = mid - 1; }
  return lo;
}
function quoteLines(srcLines, from, to, windowText, quotes) {
  const starts = lineStarts(srcLines, from, to);
  const hit = new Set();
  if (!starts.length) return [];
  for (const q of quotes) {
    const lq = loose(q);
    if (lq.length < MIN_QUOTE_LINES) continue;
    let at = windowText.indexOf(lq);
    while (at !== -1) {
      const a = lineAt(starts, at), b = lineAt(starts, at + lq.length - 1);
      for (let k = a; k <= b; k++) hit.add(starts[k].line);
      at = windowText.indexOf(lq, at + 1);
    }
  }
  return [...hit].sort((a, b) => a - b);
}

// One record against the committed tree. Grounded records follow checkOne's downgrade contract;
// REJECTED records are only annotated. `memo` holds one read per (sha, path) for the run.
function checkOneAt(rec, repoRoot, sha, memo) {
  const out = Object.assign({}, rec);
  out.confidence = Object.assign({}, rec.confidence);
  const fp = computeFingerprint(rec, repoRoot);
  out.fingerprint = fp.fingerprint;
  if (fp.unpinned) out.unpinned = true;

  const grounded = GROUNDED.has(rec.status);
  const rejected = rec.status === 'REJECTED';
  const evList = Array.isArray(rec.evidence) ? rec.evidence : (rec.evidence ? [rec.evidence] : []);
  if (!grounded && !rejected) {
    out._evidence_check = { checked: false, note: 'status not grounded — no quote check' };
    return out;
  }
  if (rejected && evList.length === 0) {
    out._evidence_check = { checked: false, note: 'REJECTED without evidence — no quote check' };
    return out;
  }

  const fail = (code) => {
    if (grounded) {
      out.status = 'SUSPECTED';
      out.missing = code;
      out.confidence.evidence_strength = 'NONE';
      out.confidence.label = 'LOW';
    }
    out._evidence_check = { checked: true, quote_found: false, quote_lines: [], note: code };
    return out;
  };

  if (!rec.file) return fail(grounded ? 'FILE_NULL_ON_GROUNDED' : 'FILE_NULL');
  const rel = repoRelative(rec.file, repoRoot);
  if (!rel) return fail('PATH_OUTSIDE_ROOT');
  const key = `${sha}:${rel}`;
  if (!memo.has(key)) memo.set(key, gitBlob(repoRoot, sha, rel));
  const blob = memo.get(key);
  if (blob.code) return fail(blob.code);
  const srcLines = blob.text.split(NL);
  const range = parseLines(rec.lines);
  if (!range) return fail('LINES_UNPARSEABLE');
  if (range[0] < 1 || range[1] > srcLines.length) return fail('LINES_OUT_OF_RANGE');

  const { from, to, text: windowText } = quoteWindow(srcLines, range);
  if (evList.length === 0) return fail('EVIDENCE_EMPTY');
  const quotes = evList.map(quoteFromEvidence).filter((q) => q.length >= 3);
  const anyFound = quotes.some((q) => quoteInWindow(windowText, q));
  if (!anyFound) return fail('EVIDENCE_QUOTE_MISMATCH');

  const lines = quoteLines(srcLines, from, to, windowText, quotes);
  const repro = rec.reproduction && rec.reproduction.status;
  if (rec.status === 'REPRODUCED' && repro !== 'REPRODUCED') {
    out.status = 'SUPPORTED';
    out.confidence.evidence_strength = 'MEDIUM';
    out._evidence_check = { checked: true, quote_found: true, quote_lines: lines, note: 'quote OK but reproduction.status != REPRODUCED -> SUPPORTED' };
    return out;
  }
  out._evidence_check = { checked: true, quote_found: true, matched_lines: `${from}-${to}`, quote_lines: lines, note: 'verified' };
  return out;
}

// Resolve <rev> to a commit sha (40 or 64 hex) in <repo-root>; null when it is not one. Throws
// GitUnavailable when git could not answer at all (missing git, not a repository, timeout).
function resolveRev(repoRoot, rev) {
  const r = String(rev == null ? '' : rev);
  if (!r || r.startsWith('-')) return null;
  const res = gitRun(repoRoot, ['rev-parse', '--verify', '--quiet', `${r}^{commit}`]);
  if (res.status === 1 && !res.err) return null;             // --quiet: exit 1, nothing said = not a commit
  if (res.status) throw new GitUnavailable(`git rev-parse failed in ${repoRoot}: ${res.err || `exit ${res.status}`}`);
  const sha = res.out.trim();
  return /^(?:[0-9a-f]{40}|[0-9a-f]{64})$/.test(sha) ? sha : null;
}

// Throws GitUnavailable (and nothing else) when git itself fails during the run. Every record's
// `_evidence_check` carries `rev`, the commit it was checked at, so a consumer can tell this
// output from a working-tree check.
function runAt(records, repoRoot, sha) {
  const memo = new Map();
  return records.map((r) => {
    const out = checkOneAt(r || {}, repoRoot, sha, memo);
    out._evidence_check = Object.assign({}, out._evidence_check, { rev: sha });
    return out;
  });
}

